tasks.solution:
판 = [[7, 2, 9],
      [4, 5, 1],
      [8, 3, 6]]
수 = int(input("부른 수: "))
for 줄 in range(3):
    for 칸 in range(3):
        if 판[줄][칸] == 수:
            판[줄][칸] = "X"
for 한줄 in 판:
    for 값 in 한줄:
        print(값, end=" ")
    print()

