challenge.solution:
크기 = int(input("크기: "))
판 = []
for 줄 in range(크기):
    한줄 = []
    for 칸 in range(크기):
        if 줄 == 칸:
            한줄.append(1)
        else:
            한줄.append(0)
    판.append(한줄)
for 한줄 in 판:
    for 값 in 한줄:
        print(값, end=" ")
    print()
